#!/usr/bin/env node
/*
 * check-js-objects: run the JavaScript attract reference (jsComanche/) and
 * compare its object table, frame by frame, with the DOS object snapshots
 * captured at 000234CE (work/replay_dos/objects-*.json, generated by
 * work/trace_replay_flight.py --objects; git-ignored, not regenerated here).
 *
 * N/A - target artefact: an oracle probe, no DOS routine.
 * record: analysis/functions/browser-attract.md#object-pass
 *
 * What is compared.  A DOS row is the whole per-slot table after every state
 * handler of 000234A4 has run and before 00024B17 draws anything.  The JS
 * object pass is stopped at the same instant by wrapping objectTransform(),
 * which updateObjectPass() calls right after the handlers.  Rows are joined
 * by the replay cursor ([00019ECC] = 13 + 8 * record), which both machines
 * step in the same 8-byte records, so a pass is the same pass on both sides.
 *
 * The one input the JS cannot reproduce is [00019DB8], the shake PRNG that
 * the timer ISR steps on wall-clock ticks and that gates the tank's aim
 * (00023E95 `test [19DB8], 0xC`).  It is DRIVEN here: before each object pass
 * the harness stores the oracle row's shake_rng into runtime.shake.rng.  That
 * is the only value taken from the oracle; every compared field is computed
 * by the JavaScript from the mission records and the replay.
 *
 * Units.  DOS positions are 10.22 and the JS keeps the authoritative 10.22
 * pair in object.dosX / dosY (x / y are the derived 16.16 render values), so
 * x, y, prev_x and prev_y are compared exactly.  A JS build that only has the
 * 16.16 pair is compared with the six low bits of DOS dropped (reported as
 * "within 64").
 *
 * Usage:
 *   node tools/check-js-objects.js [--pass N | --all] [--records N]
 *        [--slots 23-31,120-130] [--show K] [--no-rng] [--js-root DIR]
 *        [--inject-target]
 *   --pass 0..3   DEMO digit (1 = objects-demo1.json, 2 = objects-pass1.json,
 *                 3 = objects-pass2.json, 0 = objects-pass3.json)
 *   --show K      print the first K mismatches per field (default 3)
 *   --no-rng      do not inject shake_rng (shows what wall-clock nondeterminism
 *                 does to the aim)
 *   --inject-target  also take the [000219BAB] "target" byte from the oracle
 *                 (it is written by the draw pass 00024DF6, which the JS does
 *                 not carry; this isolates its effect, nothing else uses it)
 *   --fresh       do not first play the demos DOS had played before the
 *                 captured one (the per-slot arrays then start from the image)
 *   --draw        keep the drawing on (the default stubs the pixel writers out for
 *                 speed; the terrain march, which archives the per-ring horizon
 *                 00024DA4 reads, and the object pass's projection bookkeeping
 *                 still run)
 *   --js-root DIR  run a copy of jsComanche/ (e.g. the pre-change sources)
 *   --gun         the held-fire fixture (work/replay_dos/objects-gun-dos.json): DOS
 *                 with Space held on console page 0 at replay cursors 101..124
 *                 (tools/trace-falcon-objects.py --poke-from, work/trace_replay_flight.py
 *                 --objects --poke-from 101 --poke-to 125).  The same poke is applied
 *                 to the JavaScript at the same instant - after the object pass, before
 *                 the tick's weapon dispatch - and slots 127-129 (the cannon rounds)
 *                 are compared on active, x, y, heading, altitude, sprite and speed,
 *                 plus the target latch/candidate and the pending counts.  Fields that
 *                 DOS aliases above slot 30 (f9, health, hold, variant) are ignored by
 *                 construction.  Exits non-zero on any difference.
 *   --poke-from N --poke-to M --poke-page P   override the fixture's poke
 *                 (defaults 101, 125, 2): console page 0 and Space down for cursors in
 *                 [N, M); at M the page returns to P and Space is released.
 *   --align SLOT [--align-span N]  compare one slot's destruction sequence from the
 *                 frame its destruction byte first becomes non-zero on each side
 *   --find-state ADDR   per frame, every JS and DOS object whose state pointer is ADDR
 *   --trace SLOT [--trace-from F] [--trace-count N]  print one slot's JS and DOS
 *                 fields frame by frame (matching fields once, differing ones
 *                 as "JS x / DOS y")
 */

"use strict";

const fs = require("node:fs");
const path = require("node:path");
const vm = require("node:vm");

const ROOT = path.resolve(__dirname, "..");
const GUN_ORACLE = "work/replay_dos/objects-gun-dos.json";
const GUN_SLOTS = [127, 128, 129];
// The fields the cannon's rounds are judged on, and the ones reported beside them.
const GUN_FIELDS = ["active", "x", "y", "heading", "altitude", "sprite", "speed"];
const GUN_EXTRA = ["prev_x", "prev_y", "prev_alt", "aux", "state", "draw", "phase", "timer", "steer", "target"];
const ORACLES = {
  1: "work/replay_dos/objects-demo1.json",
  2: "work/replay_dos/objects-pass1.json",
  3: "work/replay_dos/objects-pass2.json",
  0: "work/replay_dos/objects-pass3.json",
};

// Per-slot arrays of the oracle, in DOS addresses (work/trace_replay_flight.py).
const FIELDS = ["active", "heading", "altitude", "prev_alt", "phase", "target", "aux",
  "timer", "steer", "flag", "variant", "f9", "health", "sprite", "speed", "x", "y",
  "prev_x", "prev_y", "state", "draw", "hold", "fire"];
const POSITIONS = new Set(["x", "y", "prev_x", "prev_y"]);
const ADDRESSES = new Set(["state", "draw", "fire"]);
// Fields whose DOS array is shorter than the slot range, or that DOS never
// writes for a slot, so the oracle's value there is not that slot's field:
//  - slot 0 is no object (its cells are other arrays' slot-130 cells);
//  - flag, variant, f9, health are 30-entry arrays (0x21F39/57/75/93, 30 bytes
//    apart), hold and fire are the dword arrays at 0x22028/0x21FB0 whose slots
//    above 31 are other tables; from slot 31 up they read neighbouring cells
//    (slot 31's own variant is f9[1]: the JS keeps it per slot, which agrees
//    while slots 1.. of the next array are unused, as they are in every pass);
//  - prev_x/prev_y/prev_alt of slot 31 are never written by 00023800: the
//    oracle shows image bytes (0x40000000, 0xD4A00000, 0xAA) in every pass.
const SHORT_ARRAYS = new Set(["flag", "variant", "f9", "health", "hold", "fire"]);
function comparable(field, slot) {
  if (slot === 0) return false;
  if (slot > 31 && SHORT_ARRAYS.has(field)) return false;
  if (slot === 31 && (field === "prev_x" || field === "prev_y" || field === "prev_alt")) return false;
  return true;
}
// The transient slots (above 31) are told apart by what DOS has in them, so
// the numbers say which routine is being measured instead of which slot
// number the two machines happened to allocate.
//   cannon round    000244E0              (the cannon's rounds, ported)
//   countermeasure  00024480 / 000244A0   (BULL / CHAF clouds, ported)
//   wreck           000237B0              (BOOM wreckage, ported)
//   shell           000234E0 / 000236D0   (enemy shells, ported)
//   weapon          000241C0 / 00024680 / 00024860 / 00024310 and anything
//                   else: the player's weapons and the enemy guided missile,
//                   which the JS still models only loosely (Unproven)
function transientClass(state) {
  if (state === 0x244e0) return "cannon round";
  if (state === 0x24480 || state === 0x244a0) return "countermeasure";
  if (state === 0x237b0) return "wreck";
  if (state === 0x234e0 || state === 0x236d0) return "shell";
  return "weapon";
}
const CLASSES = ["cannon round", "countermeasure", "wreck", "shell", "weapon"];
const SCALARS = ["frame_x", "frame_y", "alt", "chaf_threat", "bull_threat", "threat_blip", "flares"];

function parseArgs(argv) {
  const args = { pass: 1, all: false, records: Infinity, slots: null, show: 3, rng: true,
    jsRoot: path.join(ROOT, "jsComanche"), injectTarget: false };
  for (let index = 0; index < argv.length; index += 1) {
    const arg = argv[index];
    if (arg === "--pass") args.pass = Number(argv[++index]);
    else if (arg === "--all") args.all = true;
    else if (arg === "--records") args.records = Number(argv[++index]);
    else if (arg === "--slots") args.slots = argv[++index];
    else if (arg === "--show") args.show = Number(argv[++index]);
    else if (arg === "--no-rng") args.rng = false;
    else if (arg === "--inject-target") args.injectTarget = true;
    else if (arg === "--draw") args.draw = true;
    else if (arg === "--fresh") args.fresh = true;
    else if (arg === "--gun") args.gun = true;
    else if (arg === "--poke-from") args.pokeFrom = Number(argv[++index]);
    else if (arg === "--poke-to") args.pokeTo = Number(argv[++index]);
    else if (arg === "--poke-page") args.pokePage = Number(argv[++index]);
    else if (arg === "--js-root") args.jsRoot = path.resolve(argv[++index]);
    else if (arg === "--trace") args.trace = Number(argv[++index]);
    else if (arg === "--find-state") args.findState = Number(argv[++index]);
    else if (arg === "--align") args.align = Number(argv[++index]);
    else if (arg === "--align-span") args.alignSpan = Number(argv[++index]);
    else if (arg === "--trace-from") args.traceFrom = Number(argv[++index]);
    else if (arg === "--trace-count") args.traceCount = Number(argv[++index]);
    else throw new Error(`unknown argument ${arg}`);
  }
  return args;
}

function parseSlots(text) {
  if (!text) return null;
  const set = new Set();
  for (const part of text.split(",")) {
    const [low, high] = part.split("-").map(Number);
    for (let slot = low; slot <= (high === undefined ? low : high); slot += 1) set.add(slot);
  }
  return set;
}

function makeCanvas(width = 320, height = 240) {
  const context = {
    imageSmoothingEnabled: false,
    fillStyle: "#000",
    createImageData: (w, h) => ({ data: new Uint8ClampedArray(w * h * 4) }),
    putImageData() {},
    fillRect() {},
    drawImage() {},
  };
  return { width, height, getContext() { return context; } };
}

function makeSandbox() {
  const canvas = makeCanvas();
  const sandbox = {
    console,
    document: { getElementById() { return canvas; }, createElement() { return makeCanvas(0, 0); } },
    location: { href: "http://127.0.0.1:8765/F030Comanche/jsComanche/" },
    URL, TextDecoder, Uint8Array, Uint8ClampedArray, Uint16Array, Int16Array, Int32Array,
    ArrayBuffer, BigInt, Map, Set, Math, Number, Object, String, Error, TypeError,
    fetch: async (url) => {
      const relative = new URL(url).pathname.replace(/^\/F030Comanche\//, "");
      const file = path.resolve(ROOT, relative);
      if (!file.startsWith(ROOT + path.sep)) throw new Error(`loader escaped workspace: ${file}`);
      if (!fs.existsSync(file)) return { ok: false, status: 404, arrayBuffer: async () => new ArrayBuffer(0) };
      const bytes = fs.readFileSync(file);
      return {
        ok: true,
        status: 200,
        arrayBuffer: async () => bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength),
      };
    },
    requestAnimationFrame() { return 1; },
    cancelAnimationFrame() {},
  };
  sandbox.window = sandbox;
  sandbox.globalThis = sandbox;
  return { sandbox, canvas };
}

function loadSources(context, jsRoot) {
  for (const name of ["dos-fs.js", "dos-data.js", "sine-q31.js", "object-bearing.js", "dos-text-data.js", "dos-pilot.js", "dos-menu.js", "dos-damage.js", "dos-runtime.js"]) {
    vm.runInContext(fs.readFileSync(path.join(jsRoot, name), "utf8"), context, { filename: name });
  }
}

const hex = (value) => (value >>> 0).toString(16).padStart(8, "0");

// The JS object -> the oracle's per-slot record.  Absent slots read as inactive.
function readObject(object) {
  if (!object) return { active: 0 };
  const dos = "dosX" in object;
  const row = {
    active: object.active ? 1 : 0,
    heading: object.heading & 0xff,
    altitude: object.altitude & 0xff,
    prev_alt: (object.homeAlt === undefined ? object.altitude : object.homeAlt) & 0xff,
    phase: ("damageByte" in object ? (object.damageByte || object.phase) : object.phase) & 0xff,
    target: (object.targetFlag || 0) & 0xff,
    aux: (typeof object.aux === "number" ? object.aux : 0) & 0xff,
    timer: object.timer & 0xff,
    steer: (object.steerDir || 0) & 0xff,
    flag: (object.flag || 0) & 0xff,
    variant: object.variant & 0xff,
    f9: (object.f9 || 0) & 0xff,
    health: object.health & 0xff,
    sprite: (object.sprite || 0) & 0xff,
    speed: object.speed | 0,
    hold: object.hold | 0,
    state: object.stateAddr >>> 0,
    draw: object.drawAddr >>> 0,
    fire: (object.fireAddr || 0) >>> 0,
  };
  if (dos) {
    row.x = object.dosX | 0;
    row.y = object.dosY | 0;
    row.prev_x = object.homeDosX | 0;
    row.prev_y = object.homeDosY | 0;
  } else {
    row.x = (object.x << 6) | 0;
    row.y = (object.y << 6) | 0;
    row.prev_x = (object.homeX << 6) | 0;
    row.prev_y = (object.homeY << 6) | 0;
  }
  row.dos = dos;
  return row;
}

function readScalars(runtime) {
  const flight = runtime.flight;
  return {
    frame_x: flight.frameDosX | 0,
    frame_y: flight.frameDosY | 0,
    alt: runtime.view_camera_altitude & 0xff,   // [00019DFC] during the pass is the view hook's altitude
    chaf_threat: runtime.threatChaff === undefined ? (runtime.effectBFlag ? 1 : 0) : runtime.threatChaff & 0xff,
    bull_threat: runtime.threatBull === undefined ? (runtime.effectAFlag ? 1 : 0) : runtime.threatBull & 0xff,
    threat_blip: runtime.threatBlip === undefined ? 0 : runtime.threatBlip & 0xff,
    flares: runtime.effectBActive & 0xff,
  };
}

function snapshot(runtime) {
  // Values are copied now: the flight tick and the HUD that follow in the same
  // JS tick change the very objects this reads. Last object wins per slot,
  // active ones preferred: a slot can have been reused, and DOS's arrays are
  // per slot, not per allocation.
  const held = new Map();
  for (const object of runtime.objects) {
    const previous = held.get(object.slot);
    if (!previous || object.active || !previous.active) held.set(object.slot, object);
  }
  const bySlot = new Map();
  for (const [slot, object] of held) bySlot.set(slot, readObject(object));
  // The lock, candidate, console page and pending trigger counts at this same
  // instant (the DOS rows carry [00019D10], [00019D18], [00019D88], [00019DF2],
  // [00019DF3] read at 000234CE).
  const live = { latch: runtime.targetLatch, candidate: runtime.targetDefault, page: runtime.flight.weaponMode,
    trig1: runtime.flight.trigger1, trig2: runtime.flight.trigger2 };
  return { bySlot, scalars: readScalars(runtime), live };
}

// The attract plays DEMO1, DEMO2, DEMO3, DEMO0 back to back and DOS's per-slot
// arrays carry from one to the next (000227A6 clears only the active bytes),
// so a captured pass is only reproducible after the demos the DOS run played
// before it ("skip" in the oracle).  Those are run here with the drawing
// stubbed out: nothing the drawing does is read back by the object logic.
const DEMO_ORDER = [1, 2, 3, 0];
// drawTerrain itself is NOT stubbed: its ring march archives the per-ring
// horizon that the targetability test 00024DA4 reads back, so only the span
// writer (the pixels) is dropped. objectDraw is stubbed; the draw walk's
// bookkeeping (view bearing, targetability, candidate) is updateObjectPass's
// objectProjectionPass, which still runs.
const DRAW_METHODS = ["renderClear", "drawTerrainSpan", "objectDraw", "drawConsole", "drawMfdStage",
  "drawFixedInstruments", "drawHudAuthored", "drawDynamicHud", "present", "emitFrame", "recordTrace"];

async function runPass(args, pass) {
  const oracleFile = args.gun ? GUN_ORACLE : ORACLES[pass];
  const oracle = JSON.parse(fs.readFileSync(path.join(ROOT, oracleFile), "utf8"));
  if (oracle.demo_digit !== pass) throw new Error(`${oracleFile} is DEMO${oracle.demo_digit}, not ${pass}`);
  const poke = args.gun ? {
    from: args.pokeFrom ?? 101, to: args.pokeTo ?? 125, page: args.pokePage ?? 2,
  } : null;
  const rows = oracle.rows;
  const wanted = parseSlots(args.slots);
  const frames = Math.min(rows.length, args.records);

  const { sandbox, canvas } = makeSandbox();
  const context = vm.createContext(sandbox);
  loadSources(context, args.jsRoot);
  const evidence = await sandbox.ComancheDOS.loadAttractEvidence();
  const runtime = sandbox.ComancheRuntime.create({ canvas, evidence });
  if (!args.draw) for (const name of DRAW_METHODS) runtime[name] = function () {};

  const earlier = DEMO_ORDER.slice(0, DEMO_ORDER.indexOf(pass));
  if (!args.fresh) {
    for (const digit of earlier) {
      runtime.pass = digit;
      runtime.installPassEvidence(evidence.passes[digit]);
      runtime.enterDemo(digit);
      let guard = 0;
      while (runtime.mode === "demo" && runtime.demoIndex === digit && guard < 100000) {
        runtime.advanceTicks(1);
        guard += 1;
      }
    }
  }
  runtime.pass = pass;
  runtime.installPassEvidence(evidence.passes[pass]);
  runtime.enterDemo(pass);

  let current = 0;
  let captured = null;
  const originalPass = runtime.updateObjectPass;
  runtime.updateObjectPass = function (...rest) {
    if (args.rng) this.shake.rng = rows[current].shake_rng >>> 0;
    if (args.injectTarget) {
      for (const object of this.objects) object.targetFlag = rows[current].target[object.slot] || 0;
    }
    return originalPass.apply(this, rest);
  };
  const originalTransform = runtime.objectTransform;
  runtime.objectTransform = function (...rest) {
    captured = snapshot(this);
    if (poke) {
      // work/trace_replay_flight.py --poke-from, at the same instant: after the
      // object pass, with [00019ECC] already naming the next record, so the
      // keys are in place for that record's weapon dispatch at 000191B6.
      // Page [00019D88] = 0 and the Space state byte [00001AA9] = 0 (held);
      // at the end cursor the page returns and Space reads 0xFF (released).
      const cursor = rows[current].cursor;
      if (cursor >= poke.from && cursor < poke.to) {
        this.flight.weaponMode = 0;
        this.keyState[0x39] = 0;
      } else if (cursor === poke.to) {
        this.flight.weaponMode = poke.page;
        this.keyState[0x39] = 0xff;
      }
    }
    return originalTransform.apply(this, rest);
  };

  // stats[field][slot] = [match, total];  first mismatches per field
  const stats = {};
  const classStats = {};
  const near = {};
  const firsts = {};
  const scalarStats = {};
  const activeStats = { agree: 0, total: 0 };
  const dosSlots = new Set();
  for (const row of rows.slice(0, frames)) row.active.forEach((flag, slot) => { if (flag) dosSlots.add(slot); });
  const compareSlots = [...dosSlots].filter((slot) => slot !== 0 && (!wanted || wanted.has(slot))).sort((a, b) => a - b);

  const alignRows = [];
  const gun = poke ? { fields: {}, extra: {}, scalars: {}, first: [] } : null;
  let cursorMismatch = 0;
  for (current = 0; current < frames; current += 1) {
    const row = rows[current];
    const expectedCursor = 13 + 8 * runtime.demoCursor;
    if (expectedCursor !== row.cursor) { cursorMismatch += 1; if (cursorMismatch > 3) break; }
    captured = null;
    runtime.advanceTicks(1);
    if (!captured) throw new Error("object pass did not run");

    for (const name of SCALARS) {
      const key = name;
      const entry = (scalarStats[key] ||= { match: 0, total: 0, first: [] });
      entry.total += 1;
      if (captured.scalars[key] === row[key]) entry.match += 1;
      else if (entry.first.length < args.show) entry.first.push({ frame: current, cursor: row.cursor, js: captured.scalars[key], dos: row[key] });
    }
    if (gun) compareGun(args, gun, captured, row, current);
    if (args.align !== undefined) {
      const jsRow = captured.bySlot.get(args.align) || { active: 0 };
      const dosRow = {};
      for (const field of FIELDS) dosRow[field] = row[field][args.align];
      alignRows.push({ js: jsRow, dos: dosRow });
    }
    if (args.findState !== undefined) {
      // Every JS and DOS object in one state, side by side: slot numbers differ
      // wherever the two machines allocated in a different order.
      const found = [];
      for (const [slot, js] of captured.bySlot) {
        if (js.active && js.state === args.findState) found.push(`JS ${slot}: hd ${js.heading} alt ${js.altitude} tm ${js.timer} x ${js.x} y ${js.y}`);
      }
      for (let slot = 1; slot <= 130; slot += 1) {
        if (row.active[slot] && row.state[slot] === args.findState) {
          found.push(`DOS ${slot}: hd ${row.heading[slot]} alt ${row.altitude[slot]} tm ${row.timer[slot]} x ${row.x[slot]} y ${row.y[slot]}`);
        }
      }
      if (found.length) console.log(`state 0x${args.findState.toString(16)} frame ${current}: ${found.join(" | ")}`);
    }
    if (args.trace !== undefined && current >= (args.traceFrom || 0) && current < (args.traceFrom || 0) + (args.traceCount || 40)) {
      const jsRow = captured.bySlot.get(args.trace) || { active: 0 };
      const parts = [];
      for (const field of FIELDS) {
        if (!comparable(field, args.trace)) continue;
        const dos = row[field][args.trace];
        const js = jsRow[field];
        const same = ADDRESSES.has(field) ? (js >>> 0) === (dos >>> 0) : (js | 0) === (dos | 0);
        parts.push(same ? `${field}=${format(field, dos)}` : `${field}=JS ${format(field, js)} / DOS ${format(field, dos)}`);
      }
      if (row.active[args.trace] || jsRow.active) {
        console.log(`trace slot ${args.trace} frame ${current} cursor ${row.cursor}: ${parts.join("  ")}`);
      }
    }
    for (const slot of compareSlots) {
      const jsRow = captured.bySlot.get(slot) || { active: 0 };
      const dosActive = row.active[slot] ? 1 : 0;
      activeStats.total += 1;
      if (jsRow.active === dosActive) activeStats.agree += 1;
      if (!dosActive) continue;
      for (const field of FIELDS) {
        if (!comparable(field, slot)) continue;
        const dos = row[field][slot];
        let js = jsRow[field];
        if (field === "active") js = jsRow.active;
        const bucket = (stats[field] ||= {});
        const cell = (bucket[slot] ||= [0, 0]);
        cell[1] += 1;
        let equal = (js | 0) === (dos | 0);
        if (ADDRESSES.has(field)) equal = (js >>> 0) === (dos >>> 0);
        if (slot > 31) {
          const klass = transientClass(row.state[slot] >>> 0);
          const classCell = ((classStats[klass] ||= {})[field] ||= [0, 0]);
          classCell[1] += 1;
          if (equal) classCell[0] += 1;
        }
        if (equal) cell[0] += 1;
        else {
          if (POSITIONS.has(field) && !jsRow.dos && ((dos - js) | 0) >= 0 && ((dos - js) | 0) < 64) {
            (near[field] ||= {})[slot] = ((near[field] || {})[slot] || 0) + 1;
          }
          const list = (firsts[field] ||= []);
          if (list.length < args.show) list.push({ frame: current, cursor: row.cursor, slot, js, dos });
        }
      }
    }
  }

  if (args.align !== undefined) reportAlignment(args, alignRows);
  return { pass, frames, stats, classStats, near, firsts, scalarStats, activeStats, compareSlots, cursorMismatch,
    oracleName: oracle.demo_stream, gun };
}

// The cannon check.  Every frame, slots 127-129 on both sides (DOS-inactive and
// JS-inactive count as agreeing; a slot active on only one side disagrees on
// `active` and on every field the inactive side holds), then the scalars the
// dispatch and the target cycle write.  JS rows are the values at the object
// pass's end, the DOS rows the values at 000234CE: the same instant.
function compareGun(args, gun, captured, row, frame) {
  const note = (list, name, slot, js, dos) => {
    const cell = (list[name] ||= [0, 0]);
    cell[1] += 1;
    if ((js | 0) === (dos | 0) || (ADDRESSES.has(name) && (js >>> 0) === (dos >>> 0))) { cell[0] += 1; return; }
    if (gun.first.length < Math.max(args.show, 12)) gun.first.push({ frame, cursor: row.cursor, slot, name, js, dos });
  };
  for (const slot of GUN_SLOTS) {
    const js = captured.bySlot.get(slot) || { active: 0 };
    // A slot neither side has in use holds image bytes on the DOS side (and
    // nothing on this one): only `active` is compared there.
    const used = row.active[slot] || js.active;
    for (const name of GUN_FIELDS) {
      if (name !== "active" && !used) continue;
      note(gun.fields, name, slot, name === "active" ? js.active : js[name], row[name][slot]);
    }
    if (row.active[slot] || js.active) {
      for (const name of GUN_EXTRA) note(gun.extra, name, slot, js[name], row[name][slot]);
    }
  }
  for (const name of Object.keys(captured.live)) note(gun.scalars, name, 0, captured.live[name], row[name]);
}

function reportGun(gun) {
  const line = (list, title) => {
    for (const [name, [match, total]] of Object.entries(list)) {
      console.log(`   ${title} ${name.padEnd(10)} ${String(match).padStart(4)}/${String(total).padEnd(4)} ${match === total ? "ok" : "DIFFERS"}`);
    }
  };
  console.log("   cannon rounds, slots 127-129, every frame of the fixture:");
  line(gun.fields, "required");
  line(gun.extra, "reported");
  console.log("   globals at the object pass:");
  line(gun.scalars, "scalar  ");
  for (const item of gun.first) {
    console.log(`   first difference: frame ${item.frame} cursor ${item.cursor} slot ${item.slot} ${item.name}: js ${format(item.name, item.js)} dos ${format(item.name, item.dos)}`);
  }
  const bad = Object.values(gun.fields).some(([match, total]) => match !== total)
    || Object.values(gun.scalars).some(([match, total]) => match !== total);
  console.log(bad ? "FAIL gun fixture" : "PASS gun fixture: slots 127-129 and the lock/trigger globals agree on every frame");
  return !bad;
}

// The destruction sequence of one slot, compared from the frame its
// destruction byte first becomes non-zero on each side.  A hit lands on
// different frames when the player's weapons differ (they are Unproven in the
// JS), but the sequence that follows - the wreck child, the fall, the BOOM
// frames, the slot being freed - is the routine under test and is
// frame-for-frame comparable from there.
function reportAlignment(args, alignRows) {
  const first = (side) => alignRows.findIndex((entry) => entry[side].active && entry[side].phase !== 0);
  const jsStart = first("js");
  const dosStart = first("dos");
  console.log(`   alignment of slot ${args.align}: destruction byte first non-zero at frame JS ${jsStart} / DOS ${dosStart}`);
  if (jsStart < 0 || dosStart < 0) return;
  const counts = {};
  const span = Math.min(alignRows.length - jsStart, alignRows.length - dosStart, args.alignSpan || 60);
  for (let step = 0; step < span; step += 1) {
    const js = alignRows[jsStart + step].js;
    const dos = alignRows[dosStart + step].dos;
    for (const field of FIELDS) {
      if (!comparable(field, args.align) || field === "health" || POSITIONS.has(field) && field.startsWith("prev")) continue;
      const equal = ADDRESSES.has(field) ? (js[field] >>> 0) === (dos[field] >>> 0) : (js[field] | 0) === (dos[field] | 0);
      const entry = (counts[field] ||= [0, 0]);
      entry[1] += 1;
      if (equal) entry[0] += 1;
    }
  }
  console.log("   " + Object.entries(counts).map(([field, [match, total]]) => `${field} ${match}/${total}`).join("  "));
}

function format(field, value) {
  if (value === undefined) return "undef";
  if (ADDRESSES.has(field)) return `0x${(value >>> 0).toString(16)}`;
  if (POSITIONS.has(field)) return `${value | 0}(0x${hex(value)})`;
  return String(value);
}

function groupLine(field, stats, near, slots, label) {
  const bucket = stats[field] || {};
  let match = 0;
  let total = 0;
  const parts = [];
  for (const slot of slots) {
    const cell = bucket[slot];
    if (!cell) continue;
    match += cell[0];
    total += cell[1];
    if (cell[0] !== cell[1]) parts.push(`${slot}:${cell[0]}/${cell[1]}`);
  }
  if (!total) return null;
  const nearTotal = slots.reduce((sum, slot) => sum + ((near[field] || {})[slot] || 0), 0);
  const nearNote = nearTotal ? ` (+${nearTotal} within 64)` : "";
  return `   ${label} ${field.padEnd(9)} ${String(match).padStart(6)}/${String(total).padEnd(6)} ${(100 * match / total).toFixed(1).padStart(5)}%${nearNote}${parts.length ? "  short: " + parts.join(" ") : ""}`;
}

function report(result) {
  const { pass, frames, stats, classStats, near, firsts, scalarStats, activeStats, compareSlots } = result;
  const mission = compareSlots.filter((slot) => slot <= 31);
  const transient = compareSlots.filter((slot) => slot > 31);
  console.log(`== DEMO${pass} (${result.oracleName}): ${frames} frames, mission slots ${mission.join(",")}, transient slots ${transient.join(",")}`);
  if (result.cursorMismatch) console.log(`!! ${result.cursorMismatch} frames where the JS replay cursor differs from the oracle's`);
  console.log(`   slot occupancy (JS active == DOS active, over DOS-active slot-frames): ${activeStats.agree}/${activeStats.total}`);
  console.log("   per-field matches over the frames where DOS has the slot active; 'short' lists the slots below 100%:");
  for (const field of FIELDS) {
    const line = groupLine(field, stats, near, mission, "mission  ");
    if (line) console.log(line);
  }
  for (const klass of CLASSES) {
    const fields = classStats[klass];
    if (!fields) continue;
    for (const field of FIELDS) {
      const cell = fields[field];
      if (!cell) continue;
      console.log(`   ${klass.padEnd(14)} ${field.padEnd(9)} ${String(cell[0]).padStart(6)}/${String(cell[1]).padEnd(6)} ${(100 * cell[0] / cell[1]).toFixed(1).padStart(5)}%`);
    }
  }
  console.log("   scalars (all frames):");
  for (const name of SCALARS) {
    const entry = scalarStats[name];
    console.log(`   ${name.padEnd(11)} ${entry.match}/${entry.total}`);
  }
  console.log("   first mismatches:");
  for (const field of FIELDS) {
    for (const item of firsts[field] || []) {
      console.log(`   ${field.padEnd(9)} frame ${item.frame} cursor ${item.cursor} slot ${item.slot}: js ${format(field, item.js)} dos ${format(field, item.dos)}`);
    }
  }
  for (const name of SCALARS) {
    for (const item of scalarStats[name].first) {
      console.log(`   ${name.padEnd(11)} frame ${item.frame} cursor ${item.cursor}: js ${item.js} dos ${item.dos}`);
    }
  }
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  if (args.gun) { args.pass = 1; args.records = Math.min(args.records, 45); }
  const passes = args.all ? [1, 2, 3, 0] : [args.pass];
  for (const pass of passes) {
    const result = await runPass(args, pass);
    report(result);
    if (result.gun && !reportGun(result.gun)) process.exitCode = 1;
  }
}

main().catch((error) => {
  console.error(error.stack || error.message || error);
  process.exitCode = 1;
});
